#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: NarWal store submission (board #17242): CHECKLIST.md sections 1, 5
# and 6, the steps only a person can take. The wizard opens each page, copies
# the text to paste from chrome-web-store.md and edge-add-ons.md (so it stays
# the same as those files), and waits. It registers, pays and submits
# nothing: every account, fee and Submit/Publish press is yours.
#
# Run from anywhere:  docs/release/submit-wizard.sh
# Re-run at any time: finished stages are remembered in ~/.narwal-submit-wizard
# and offered for skipping (Partner Center verification can take days).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=14

DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$DIR/../.." && pwd)"
CHROME_MD="$DIR/chrome-web-store.md"
EDGE_MD="$DIR/edge-add-ons.md"
ENV_FILE="${NARWAL_WIZARD_STATE:-$HOME/.narwal-submit-wizard}"
VERSION="$(sed -n 's/^  "version": "\(.*\)",$/\1/p' "$REPO/packages/extension/package.json" | head -n1)"
PRIVACY_URL="https://prosoftip.com/narwal/privacy"
CHROME_CONSOLE="https://chrome.google.com/webstore/devconsole"
EDGE_CENTER="https://partner.microsoft.com/dashboard/microsoftedge/overview"

# block FILE MARKER prints the first ```text block after the first line that
# contains MARKER (a fixed string).
block() {
  awk -v m="$2" '
    !found && index($0, m) { found = 1; next }
    found && !inside && /^```text$/ { inside = 1; next }
    inside && /^```$/ { exit }
    inside { print }
  ' "$1"
}

# to_clipboard copies stdin to the clipboard; returns 1 when there is none.
to_clipboard() {
  if command -v pbcopy >/dev/null 2>&1; then pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then wl-copy
  elif command -v xclip >/dev/null 2>&1; then xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then clip.exe
  else return 1; fi
}

# paste_text "what" "where" TEXT copies TEXT, shows it, and waits.
paste_text() {
  local what="$1" where="$2" text="$3"
  if [[ -z "$text" ]]; then
    warn "could not find \"$what\" in the listing files; copy it from docs/release by hand"
  elif printf '%s' "$text" | to_clipboard; then
    printf '  %s✓ copied%s %s\n' "$GREEN" "$RESET" "$what"
    printf '%s\n' "$text" | awk 'NR <= 6 { print "      " $0 }'
    [[ $(printf '%s\n' "$text" | wc -l) -gt 6 ]] && note "      … (all of it is on the clipboard)"
  else
    printf '  %sCopy this%s (%s):\n\n%s\n\n' "$BOLD" "$RESET" "$what" "$text"
  fi
  pause "Paste it into $where, then press Enter"
}

# skip_done KEY: true when this stage was finished before and you skip it.
skip_done() {
  local when
  when=$(_existing "$1" || true)
  [[ -n "$when" ]] || return 1
  note "You finished this stage on $when."
  confirm "Skip it?"
}

# mark_done KEY records the stage as finished.
mark_done() { write_env "$1" "$(date -u +%Y-%m-%dT%H:%MZ)"; }

sha256_of() {
  if command -v shasum >/dev/null 2>&1; then shasum -a 256 "$1" | cut -d' ' -f1
  else sha256sum "$1" | cut -d' ' -f1; fi
}

banner "NarWal $VERSION: Chrome Web Store and Edge Add-ons submission"

# ── 1. The package ────────────────────────────────────────────────────────
stage "The store package (narwal-$VERSION-store.zip)"
ZIP="$REPO/packages/extension/release/narwal-$VERSION-store.zip"
if [[ ! -f "$ZIP" || ! -f "$ZIP.sha256" ]]; then
  say "No local build of narwal-$VERSION-store.zip. Getting it from the GitHub release v$VERSION."
  if ! command -v gh >/dev/null 2>&1; then
    warn "gh is not installed. Download narwal-$VERSION-store.zip and its .sha256 from:"
    open_url "https://github.com/ProSoftIP/NarWal/releases/tag/v$VERSION"
    ask ZIP_PATH "Path of the downloaded zip:"
    ZIP="$ZIP_PATH"
  else
    DL="$HOME/Downloads/narwal-$VERSION-store"
    mkdir -p "$DL"
    gh release download "v$VERSION" --repo ProSoftIP/NarWal -p "narwal-$VERSION-store.zip*" -D "$DL" --clobber
    ZIP="$DL/narwal-$VERSION-store.zip"
  fi
fi
[[ -f "$ZIP" && -f "$ZIP.sha256" ]] || { warn "missing $ZIP or $ZIP.sha256"; exit 1; }
WANT="$(cut -d' ' -f1 < "$ZIP.sha256")"
GOT="$(sha256_of "$ZIP")"
if [[ "$WANT" != "$GOT" ]]; then
  warn "SHA-256 mismatch: the file is $GOT, the release says $WANT. Do not upload it."
  exit 1
fi
printf '  %s✓ SHA-256 matches%s %s\n' "$GREEN" "$RESET" "$GOT"
say "Upload exactly this file to both stores:"
say "  $ZIP"
open_url "$(dirname "$ZIP")"
pause "Press Enter to continue"

# ── 2. Chrome developer account (CHECKLIST section 1) ─────────────────────
stage "Chrome Web Store developer account (ProSoft IP Google account)"
if ! skip_done CHROME_ACCOUNT_DONE; then
  say "Use the ProSoft IP Google account (the one that owns prosoftip.com),"
  say "not a personal account: the account that publishes an item owns it."
  step "First check 2-Step Verification is on for that account:"
  open_url "https://myaccount.google.com/signinoptions/twosv"
  pause "2-Step Verification is on? Press Enter"
  open_url "$CHROME_CONSOLE"
  step "Sign in as the ProSoft IP Google account."
  step "Accept the developer agreement and pay the one-time US\$5 fee (you pay; the wizard does not)."
  step "Publisher name: ProSoft IP"
  step "Contact email: info@prosoftip.com, then open the verification email and verify it."
  pause "Press Enter when the dashboard opens and the email is verified"
  mark_done CHROME_ACCOUNT_DONE
fi

# ── 3. Trader status (CHECKLIST section 1) ────────────────────────────────
stage "Chrome: trader status (EU Digital Services Act)"
if ! skip_done CHROME_TRADER_DONE; then
  open_url "$CHROME_CONSOLE"
  step "In the dashboard's Account page, where it asks whether you are a trader: answer \"trader\"."
  step "Give ProSoft IP's business address, email (info@prosoftip.com) and phone."
  note "The store shows them on the listing in the EU."
  pause "Press Enter when the trader details are saved"
  mark_done CHROME_TRADER_DONE
fi

# ── 4. Partner Center (CHECKLIST section 1) ───────────────────────────────
stage "Microsoft Partner Center: Microsoft Edge program (company account)"
if ! skip_done EDGE_ACCOUNT_DONE; then
  open_url "https://partner.microsoft.com/dashboard/microsoftedge/"
  step "Sign in with the ProSoft IP Microsoft account."
  step "Register for the Microsoft Edge program as a COMPANY account (no fee)."
  step "Publisher display name: ProSoft IP. Contact: info@prosoftip.com."
  note "Microsoft verifies company accounts; it can take a few business days."
  note "You can do the Chrome stages now and stop before stage 10 (Ctrl-C) until it is verified."
  pause "Press Enter when the registration is sent"
  mark_done EDGE_ACCOUNT_DONE
fi

# ── 5. Chrome: new item (CHECKLIST section 5) ─────────────────────────────
stage "Chrome: new item, upload the zip"
if ! skip_done CHROME_UPLOAD_DONE; then
  open_url "$CHROME_CONSOLE"
  step "Press \"New item\"."
  step "Upload: $ZIP"
  note "The Finder/Files window from stage 1 shows the file."
  pause "Press Enter when the upload is accepted and the item page is open"
  mark_done CHROME_UPLOAD_DONE
fi

# ── 6. Chrome: Store listing tab ──────────────────────────────────────────
stage "Chrome: Store listing tab"
if ! skip_done CHROME_LISTING_DONE; then
  say "Open the item's \"Store listing\" tab."
  paste_text "detailed description" "Description" "$(block "$CHROME_MD" '**Detailed description:**')"
  step "Category: Productivity → Workflow & Planning (second choice: Developer Tools)."
  step "Language: English."
  step "Store icon: images/store-icon-128.png"
  step "Screenshots, in this order: store-1-replay.jpg, store-2-mark.jpg, store-3-saved.jpg, store-4-model.jpg, store-5-choice.jpg"
  step "Small promo tile: promo-small-440x280.jpg. Marquee promo tile: promo-marquee-1400x560.jpg"
  open_url "$DIR/images"
  step "Official URL: leave as none (prosoftip.com is not a verified site yet)."
  paste_text "homepage URL" "Homepage URL" "https://prosoftip.com/"
  paste_text "support URL" "Support URL" "https://prosoftip.com/contact.php"
  pause "Press Enter after \"Save draft\""
  mark_done CHROME_LISTING_DONE
fi

# ── 7. Chrome: Privacy practices tab ──────────────────────────────────────
stage "Chrome: Privacy practices tab"
if ! skip_done CHROME_PRIVACY_DONE; then
  say "Open the item's \"Privacy practices\" tab."
  paste_text "single purpose" "Single purpose description" "$(block "$CHROME_MD" '### Single purpose')"
  for perm in offscreen scripting tabs webNavigation storage unlimitedStorage alarms; do
    paste_text "justification for $perm" "the \"$perm\" justification box" "$(block "$CHROME_MD" "**$perm**")"
  done
  paste_text "host permission justification" "the host permission justification box" "$(block "$CHROME_MD" '**Host permission')"
  step "\"Are you using remote code?\": No."
  paste_text "remote code justification" "the remote code box (if it asks)" "$(block "$CHROME_MD" '### Remote code')"
  say "Data usage: tick ONLY these two:"
  step "Personal communications (the narration audio, sent to OpenAI only if the user picks OpenAI)."
  step "Authentication information (the user's own OpenAI key, sent to OpenAI only)."
  note "Leave the rest unticked: page content and activity stay on the computer."
  say "Tick all three certifications:"
  step "I do not sell or transfer user data to third parties, outside of the approved use cases."
  step "I do not use or transfer user data for purposes that are unrelated to my item's single purpose."
  step "I do not use or transfer user data to determine creditworthiness or for lending purposes."
  paste_text "privacy policy URL" "Privacy policy URL" "$PRIVACY_URL"
  pause "Press Enter after \"Save draft\""
  mark_done CHROME_PRIVACY_DONE
fi

# ── 8. Chrome: Distribution and test instructions ─────────────────────────
stage "Chrome: Distribution tab and test instructions"
if ! skip_done CHROME_DISTRIBUTION_DONE; then
  say "Open the item's \"Distribution\" tab."
  step "Visibility: Unlisted (only people with the link; not in search)."
  step "Regions: All regions."
  step "Payments: Free."
  pause "Press Enter after \"Save draft\""
  say "Open the \"Test instructions\" tab."
  paste_text "reviewer test instructions" "Test instructions" "$(block "$CHROME_MD" '## Test instructions for the reviewer')"
  pause "Press Enter after \"Save draft\""
  mark_done CHROME_DISTRIBUTION_DONE
fi

# ── 9. Chrome: submit ─────────────────────────────────────────────────────
stage "Chrome: submit for review (your press)"
if ! skip_done CHROME_SUBMIT_DONE; then
  say "Check before you press:"
  step "Visibility is Unlisted."
  step "The uploaded package is version $VERSION."
  step "In the submit dialog, turn OFF publishing automatically after review, so you choose the publish time."
  note "Review takes a few days up to about two weeks (broad host access). Do not upload again while it is in review."
  if confirm "Have you pressed \"Submit for review\"?"; then
    ask CHROME_ITEM_ID "The item ID (the 32 letters in the dashboard URL), or Enter to skip:"
    [[ -n "${CHROME_ITEM_ID:-}" ]] && write_env CHROME_ITEM_ID "$CHROME_ITEM_ID"
    mark_done CHROME_SUBMIT_DONE
  else
    SKIPPED+=("Chrome: Submit for review")
  fi
fi

# ── 10. Edge: new extension (CHECKLIST section 5) ─────────────────────────
stage "Edge: create the extension, upload the same zip, Availability"
if ! skip_done EDGE_UPLOAD_DONE; then
  note "Needs the Partner Center account from stage 4 to be verified."
  open_url "$EDGE_CENTER"
  step "Press \"Create new extension\"."
  step "Upload the SAME file: $ZIP"
  pause "Press Enter when the package is accepted"
  say "Availability:"
  step "Visibility: Hidden (Edge's word for unlisted)."
  step "Markets: all markets."
  pause "Press Enter after Save"
  mark_done EDGE_UPLOAD_DONE
fi

# ── 11. Edge: Properties ──────────────────────────────────────────────────
stage "Edge: Properties"
if ! skip_done EDGE_PROPERTIES_DONE; then
  step "Category: Productivity."
  step "Does it access personal information: Yes (the microphone, and the audio sent to OpenAI when the user picks OpenAI)."
  paste_text "privacy policy URL" "Privacy policy URL" "$PRIVACY_URL"
  paste_text "website" "Website" "https://prosoftip.com/"
  paste_text "support contact" "Support contact info" "info@prosoftip.com"
  step "Mature content: No."
  pause "Press Enter after Save"
  mark_done EDGE_PROPERTIES_DONE
fi

# ── 12. Edge: Store listing ───────────────────────────────────────────────
stage "Edge: Store listing (English)"
if ! skip_done EDGE_LISTING_DONE; then
  # Edge's own first paragraph, then the Chrome description from its second
  # paragraph on (edge-add-ons.md: "unchanged, with one change to the first
  # paragraph").
  EDGE_DESC="$(block "$EDGE_MD" '**Description**')

$(block "$CHROME_MD" '**Detailed description:**' | awk 'seen { print } /^$/ { seen = 1 }')"
  paste_text "description (Edge first paragraph + the Chrome text)" "Description" "$EDGE_DESC"
  paste_text "short description" "Short description (only if it asks)" "Record a narrated walkthrough of one tab: page evidence and your microphone, saved on this computer."
  paste_text "search terms (one per line)" "Search terms, one per box" "$(block "$EDGE_MD" '**Search terms**')"
  step "Extension logo: images/edge-logo-300.png"
  step "Screenshots: the same five, store-1-replay.jpg to store-5-choice.jpg"
  open_url "$DIR/images"
  step "Small promotional tile: promo-small-440x280.jpg. Large promotional tile: promo-marquee-1400x560.jpg"
  note "YouTube video: none."
  pause "Press Enter after Save"
  mark_done EDGE_LISTING_DONE
fi

# ── 13. Edge: certification notes and publish ─────────────────────────────
stage "Edge: notes for certification, then Publish (your press)"
if ! skip_done EDGE_SUBMIT_DONE; then
  paste_text "notes for certification" "Notes for certification" "$(block "$EDGE_MD" '## Notes for certification')"
  step "Check: Visibility Hidden, package version $VERSION."
  note "Certification takes up to 7 business days. Hidden means only people with the link can find it."
  warn "Partner Center has no \"publish later\" switch that this kit has confirmed: Edge may go live (Hidden) as soon as it passes."
  if confirm "Have you pressed \"Publish\"?"; then
    ask EDGE_PRODUCT_ID "The product ID from the Partner Center URL, or Enter to skip:"
    [[ -n "${EDGE_PRODUCT_ID:-}" ]] && write_env EDGE_PRODUCT_ID "$EDGE_PRODUCT_ID"
    mark_done EDGE_SUBMIT_DONE
  else
    SKIPPED+=("Edge: Publish")
  fi
fi

# ── 14. After approval: existing unpacked users (CHECKLIST section 6) ─────
stage "After a store approves it: move from the unpacked build"
say "Do this only when a store listing is live. Each store gives NarWal a new ID,"
say "and recordings are kept per ID, so the unpacked build's recordings do not move by themselves."
step "In the unpacked NarWal: Saved recordings → Export bundle, for each recording to keep."
step "edge://extensions → remove the unpacked NarWal."
step "Install NarWal from the store link (Unlisted/Hidden: from the item's link)."
step "In the store NarWal: Saved recordings → \"Open a shared recording\" for each exported bundle."
warn "Do not run the unpacked and the store build side by side: two libraries, same shortcuts."
pause "Press Enter to finish"

finish
